208	  // Success and redirect responses receive all prepared headers.
209	  // Error responses (4xx/5xx) only receive headers explicitly staged as `event.res.errHeaders`
210	  // to avoid leaking success-only headers (caching, content negotiation, ...) into errors.
211	  if (val.status >= 400) {
212	    preparedHeaders = preparedRes?.[kEventResErrHeaders];
213	  }
214	
215	  // Merge prepared headers unless there is nothing to merge or a custom error
216	  // render is returned from `onError`. `event.res.headers` is created lazily on first
217	  // access, so it can be present but empty -- nothing to merge then either.
218	  if (preparedHeaders && !nested && !preparedHeaders.keys().next().done) {
219	    // Never merge *into* `val.headers`: the handler owns that `Response` and may reuse it
220	    // (module-level constant, memoized fallback, ...). Merging in place makes
221	    // request-scoped headers stick to it permanently, and because `set-cookie` is
222	    // appended rather than set, one request's session cookie would then be re-emitted to
223	    // every later client receiving that same object. Build a new response instead.
224	    return new FastResponse(nullBody(event.req.method, val.status) ? null : val.body, {
225	      status: val.status,
226	      statusText: val.statusText,
227	      headers: mergeHeaders(val.headers, preparedHeaders),
228	    }) as Response;
229	  }
230	
231	  // Strip the body for HEAD requests (runtimes usually do this, but keep
232	  // self-consistent for web-mode / service-worker consumers). Covers the
233	  // in-place merge path above, which previously returned the body intact.
234	  return event.req.method === "HEAD" && val.body !== null
235	    ? (new FastResponse(null, {
236	        status: val.status,
237	        statusText: val.statusText,
238	        headers: val.headers,
239	      }) as Response)
240	    : val;
241	}
242	
243	function mergeHeaders(base: HeadersInit, overrides: Headers, target = new Headers(base)): Headers {
244	  for (const [name, value] of overrides) {
245	    if (name === "set-cookie") {
246	      target.append(name, value);
247	    } else {
248	      target.set(name, value);
249	    }
250	  }
251	  return target;
252	}
253	
254	const frozen =
255	  (name: string) =>
256	  (...args: any[]) => {
257	    throw new Error(`Headers are frozen (${name} ${args.join(", ")})`);
258	  };
259	
260	class FrozenHeaders extends Headers {
261	  override set = frozen("set");
262	  override append = frozen("append");
263	  override delete = frozen("delete");
264	}
265	
266	const emptyHeaders = /* @__PURE__ */ new FrozenHeaders({
267	  "content-length": "0",
268	});
269	
270	const jsonHeaders = /* @__PURE__ */ new FrozenHeaders({
271	  "content-type": "application/json;charset=UTF-8",
272	});
273	
274	function prepareResponseBody(
275	  val: unknown,
276	  event: H3Event,
277	  config: H3Config,
278	): Partial<HTTPResponse> {
279	  // Empty Content
280	  if (val === null || val === undefined) {
281	    return { body: "", headers: emptyHeaders };
282	  }
283	
284	  const valType = typeof val;
285	
286	  // Text
287	  if (valType === "string") {
288	    // Default header is text/plain we don't set it for performance reasons
289	    // new Response("").headers.get('content-type') === "text/plain;charset=UTF-8"
290	    return { body: val as string };
291	  }
292	
293	  // Buffer (should be before JSON)
294	  if (val instanceof Uint8Array) {
295	    // Set on the returned headers, not `event.res` (already cleared by the caller):
296	    // writing to `event.res.headers` here would recreate it post-clear and be discarded.
297	    return {
298	      body: val as BufferSource,
299	      headers: new Headers({ "content-length": val.byteLength.toString() }),
300	    };
301	  }
302	
303	  // Partial Response
304	  if (val instanceof HTTPResponse || (val as any)?.[kHTTPResponse] === true) {
305	    return val;
306	  }
307	
308	  // JSON
309	  if (isJSONSerializable(val, valType)) {
310	    return {
311	      body: JSON.stringify(val, undefined, config.debug ? 2 : undefined),
312	      headers: jsonHeaders,
313	    };
314	  }
315	
316	  // BigInt
317	  if (valType === "bigint") {
318	    return { body: val.toString(), headers: jsonHeaders };
319	  }
320	
321	  // Blob
322	  if (val instanceof Blob) {
323	    const headers = new Headers({
324	      "content-type": val.type,
325	      "content-length": val.size.toString(),
326	    });
327	
328	    // File
329	    let filename = (val as File).name;
330	    if (filename) {
